model.setObjective(obj, GRB.MINIMIZE)

# Constraint: exactly one candidate per slot
infeasible = False
for slot in data:
    sid = slot["slot_id"]
    # apply global feasibility filters
    valid = []
    for cand in slot["candidates"]:
        ok = True
        if sid in feasibility_checks:
            ok = feasibility_checks[sid](cand)
        if ok:
            valid.append(cand)
    if not valid:
        infeasible = True
    model.addConstr(
        gp.quicksum(x[(sid, c["product_id"])] for c in valid) == 1,
        name=f"slot_{sid}"
    )
    # forbid any non-valid candidates
    for cand in slot["candidates"]:
        if cand not in valid:
            model.addConstr(x[(sid, cand["product_id"])] == 0)

if infeasible:
    print(json.dumps({"status": "infeasible", "selected_products": [], "total_price": None}))
else:
    model.optimize()
    if model.status == GRB.OPTIMAL:
        selected = []
        total = 0.0
        for slot in data:
            sid = slot["slot_id"]
            qty = slot["quantity"]
            for cand in slot["candidates"]:
                if x[(sid, cand["product_id"])].X > 0.5:
                    selected.append({
                        "slot_id": sid,
                        "product_id": cand["product_id"],
                        "quantity": qty,
                        "unit_price": cand["price"]
                    })
                    total += cand["price"] * qty
        print(json.dumps({
            "status": "optimal",
            "selected_products": selected,
            "total_price": total
        }))
    else:
        print(json.dumps({"status": "infeasible", "selected_products": [], "total_price": None}))
